import { type ComponentType, createElement } from 'react';
import { hydrateRoot } from 'react-dom/client';
import { IslandSlot } from '../components/IslandSlot.js';
import type { HydrationStrategy } from '../types.js';

/**
 * Async loader that returns a React component.
 * The registry generator handles extraction from ComponentConfig at build time.
 */
type ComponentLoader = () => Promise<React.ComponentType<unknown>>;

/**
 * Registry entry with loader and strategy.
 * Generated by the scanner from withHydration metadata.
 */
interface ComponentRegistryEntry {
  loader: ComponentLoader;
  strategy: HydrationStrategy;
}

/**
 * Registry mapping component names to their loaders and strategies.
 * Generated by virtual:conloca-hydration-registry at build time.
 */
export type ComponentRegistry = Record<string, ComponentRegistryEntry>;

/**
 * Hydrate a single element with its corresponding React component.
 */
async function hydrateElement(element: HTMLElement, entry: ComponentRegistryEntry): Promise<void> {
  const componentName = element.dataset.hydrate;
  const propsJson = element.dataset.props || '{}';

  if (!componentName) {
    console.warn('[Conloca Hydration] Element missing data-hydrate attribute');
    return;
  }

  try {
    const props = JSON.parse(propsJson);
    const Component = await entry.loader();
    hydrateRoot(element, createElement(Component, props));

    // Clean up data attributes after successful hydration
    delete element.dataset.hydrate;
    delete element.dataset.hydrateStrategy;
    delete element.dataset.props;
  } catch (error) {
    console.error(`[Conloca Hydration] Failed to hydrate ${componentName}:`, error);
  }
}

/**
 * Hydrate when the element becomes visible in the viewport. A `display:contents`
 * wrapper has no box and never intersects, so its element children are observed
 * instead (the wrapper itself only when it has none), as Astro's `client:visible` does.
 */
function hydrateOnVisible(element: HTMLElement, hydrate: () => void): void {
  const observer = new IntersectionObserver(
    (entries, obs) => {
      if (!entries.some((ioEntry) => ioEntry.isIntersecting)) return;
      obs.disconnect();
      hydrate();
    },
    { rootMargin: '50px' },
  );
  const targets = element.children.length > 0 ? [...element.children] : [element];
  for (const target of targets) observer.observe(target);
}

/**
 * Hydrate when browser is idle.
 * Uses requestIdleCallback with setTimeout fallback for Safari.
 */
function hydrateOnIdle(hydrate: () => void): void {
  const scheduleIdle =
    window.requestIdleCallback ??
    ((cb: IdleRequestCallback) => window.setTimeout(() => cb({ didTimeout: false, timeRemaining: () => 50 }), 1));

  scheduleIdle(hydrate, { timeout: 2000 });
}

/** Run `hydrate` for `element` by its strategy: now (`load` and unknown strategies), when visible, or when idle. */
function schedule(element: HTMLElement, strategy: string | undefined, hydrate: () => void): void {
  if (strategy === 'visible') hydrateOnVisible(element, hydrate);
  else if (strategy === 'idle') hydrateOnIdle(hydrate);
  else hydrate();
}

/** One hydrated fragment component's chunk, loading. */
// biome-ignore lint/suspicious/noExplicitAny: island props are whatever JSON the server wrote
type FragmentLoad = Promise<ComponentType<any>>;
type FragmentLoader = () => FragmentLoad;

/**
 * Registry key → loader of each hydrated fragment component, one chunk each.
 * Generated by virtual:conloca-hydration-registry at build time.
 */
export type FragmentRegistry = Readonly<Record<string, FragmentLoader>>;

/** The children HTML the server left for island `id`: its slot inside the island, else its `<template>` sibling. */
function islandChildrenHtml(island: HTMLElement, id: string): string | undefined {
  for (const slot of island.querySelectorAll<HTMLElement>('conloca-island-slot')) {
    if (slot.dataset.conlocaIslandSlot === id) return slot.innerHTML;
  }
  const next = island.nextElementSibling;
  return next instanceof HTMLTemplateElement && next.dataset.conlocaIslandSlot === id ? next.innerHTML : undefined;
}

/** Hydrate one island in its own root, with the id prefix its server root used, reusing its children's HTML. */
async function hydrateIsland(island: HTMLElement, id: string, key: string, load: FragmentLoader): Promise<void> {
  try {
    const Component = await load();
    const props = JSON.parse(island.dataset.props ?? '{}');
    const html = islandChildrenHtml(island, id);
    const children = html === undefined ? undefined : createElement(IslandSlot, { id, html });
    hydrateRoot(island, createElement(Component, children === undefined ? props : { ...props, children }), {
      identifierPrefix: id,
    });
  } catch (error) {
    console.error(`[Conloca Hydration] Failed to hydrate ${key}:`, error);
  }
}

/** Schedule every fragment island on the page; each key's loader runs at most once, when its first island hydrates. */
function initFragmentIslands(fragmentRegistry: FragmentRegistry): void {
  const loads = new Map<string, FragmentLoad>();
  // Own keys only: a page's `data-conloca-component` must never reach `constructor` or other prototype members.
  const loaders = new Map(Object.entries(fragmentRegistry));
  for (const island of document.querySelectorAll<HTMLElement>('conloca-island[data-conloca-island]')) {
    const id = island.dataset.conlocaIsland ?? '';
    const key = island.dataset.conlocaComponent ?? '';
    const loader = loaders.get(key);
    if (!loader) {
      console.warn(`[Conloca Hydration] Unknown fragment component: ${key}`);
      continue;
    }
    const loadOnce = () => {
      const loading = loads.get(key) ?? loader();
      loads.set(key, loading);
      return loading;
    };
    schedule(island, island.dataset.hydrateStrategy, () => void hydrateIsland(island, id, key, loadOnce));
  }
}

/**
 * Initialize hydration for all marked components on the page: Puck blocks
 * (`[data-hydrate]`, strategy from the registry) and fragment islands
 * (`conloca-island`, strategy from the markup).
 */
export function initHydration(registry: ComponentRegistry, fragmentRegistry: FragmentRegistry = {}): void {
  const elements = document.querySelectorAll<HTMLElement>('[data-hydrate]');

  for (const element of elements) {
    const componentName = element.dataset.hydrate;
    if (!componentName) continue;

    const entry = registry[componentName];
    if (!entry) {
      console.warn(`[Conloca Hydration] Unknown component: ${componentName}`);
      continue;
    }

    // Use strategy from registry (set at build time via withHydration)
    schedule(element, entry.strategy, () => void hydrateElement(element, entry));
  }
  initFragmentIslands(fragmentRegistry);
}
